    editions: null,
    editionsError: null,
    editionsPromise: null,
    editionTaskStatus: null,
    taskIdsByMode: {},   // mode → {taskId: 1}：任务点位按当前模式过滤
    taskIdsPrompt: {},   // mode → Promise，避免重复加载 tasks.<mode>.json
    taskIdFilterMode: null, // 当前已应用的任务点位过滤模式（null = 未过滤）
    taskIdFilterError: null,
    // —— R77：任务 / 剧情面板的每条开关；R212：分组图层勾选与可并行判定 ——
    taskPointSwitches: {},  // mode → {"tasks:<id>": bool}：每条任务 / 剧情自己的显示开关
    // R212：普通 / 剧情任务 × 已完成 / 未完成，四个勾选默认全开（不静默隐藏已有数据）。
    taskLayerFilters: { tasks: { done: true, todo: true }, stories: { done: true, todo: true } },
    taskParallelOnly: false, // 独立的「可并行推进」；默认关（新开关一律默认关）
    taskLayerFold: {},       // kind → 分组是否收起（只影响 DOM，不影响勾选值）
    taskGroupNodes: { tasks: {}, stories: {} }, // 本次 renderOverlay 建出的节点：kind → groupId → [node]
    taskContext: null,      // 右键选单当前指向的分组 {kind, id, name}
    taskProgressSnap: {},   // 当前模式的任务进度桶（只读 localStorage 快照）
    storyStepCounts: {},    // R104：剧情 id → 步骤总数（判断剧情点是否「进行中」）
    taskMetaByMode: {},     // mode → {prereq: {id: [{taskId, logic}]}, hasPrereq: bool}
    taskPrereqError: {},    // mode → 加载 tasks.<mode>.json 失败原因（可并行判定随之退化）

