    loadout: {},         // 已装备物品：{槽位节点 id → 物品 id}；根槽位 key 即节点 id，子槽是 "父/子"
    sens: null,          // 游戏内灵敏度（0–1；null = 用户还没填）
    items: null,         // data/items.json 里的 items 表（进配装视图时才懒加载）
    fleaPrices: null,    // R20.5：data/flea-prices.json 行情缓存（独立文件，不覆盖 items.json）
    fleaLevels: null,    // R20.6b：data/flea-levels.json（跳蚤市场上架所需等级，sidecar 文件）
    caliberGroups: null, // R20.5c：data/caliber-groups.json（口径→弹药类别，给口径色块配色）
    caliberGroupsPromise: null,
