    gearTable: null,     // 配装主列表的句柄（createTable 的返回值）
    focus: "helmet",     // 当前选中的槽位节点 id（根槽位 key，或 "父/子槽"）
    slotTree: null,      // 槽位节点树（每次装备变化后按父装备真实定义重建）
    audit: null,         // data/items.json 的 audit（七类件数 / 重复归类 / 待审核 / 材质表 / 分类 id）
    pending: [],         // 需要用户知道的提示（如换父装备后自动卸下的附件）
    priceMode: "last",   // 价格档位：last / avg24h / avg7d（与 js/market.js 同一套市场口径）
    gwOnlyTrader: false,  // R20.4：候选表「仅商人可买」开关（只影响显示）
    lwSearch: "",        // 工作台顶栏的搜索词（与表格内部搜索状态同步）
    lwMin: null,         // 价格区间下限（null = 不限）
