    presets: { loadout: null, weapon: null },   // 后端返回的整包（null = 还没取）
    presetId: null,      // 当前载入的人物装备预设 id（覆盖保存 / 重命名用）
    presetError: null,   // 预设接口的最近一次错误（界面原样显示，不假装成功）
