    arow.appendChild(asel);
    box4.appendChild(arow);
    var ainfo = elTag("div", "am-sim-armorinfo");
    ainfo.setAttribute("data-sim", "armor-info");
    box4.appendChild(ainfo);
    var aslots = elTag("div", "am-sim-armorslots");
    aslots.setAttribute("data-sim", "armor-slots");
    box4.appendChild(aslots);
    var hrow = elTag("div", "am-sim-row");
